return {
    ["Pass the Word"] = { fr = "Passe-mot", es = "Pasa la palabra", de = "Wortweitergabe" },
    ["Word-guessing party game for four, two teams of two, inspired by the classic TV game: one-word clues, a 4-round qualification, then a 5-level final with a prize pyramid."] = { fr = "Jeu de mots à faire deviner pour quatre, en deux équipes de deux, inspiré du jeu télévisé classique : des indices d'un seul mot, une qualification en 4 manches, puis une finale en 5 paliers avec sa pyramide de gains.", es = "Juego de adivinar palabras para cuatro, dos equipos de dos, inspirado en el clásico concurso de televisión: pistas de una sola palabra, una clasificación en 4 rondas y una final de 5 niveles con su pirámide de premios.", de = "Worträtsel-Partyspiel für vier, zwei Zweierteams, nach dem Vorbild der klassischen TV-Rateshow: Hinweise aus einem Wort, eine Qualifikation in 4 Runden, dann ein Finale über 5 Stufen mit Gewinnpyramide." },
